        "evidence_lines": [
          "《隋書》卷八〇《譙國夫人傳》：“譙國夫人者，高涼洗氏之女也。……夫人兄南梁州刺史挺，恃其富强，侵掠傍郡，嶺表苦之。夫人多所規諫，由是怨隙止息，海南、儋耳歸附者千餘洞。梁大同初，羅州刺史馮融聞夫人有志行，爲其子高涼太守寶娉以爲妻。融本北燕苗裔。初，馮弘之投高麗也，遣融大父業以三百人浮海歸宋，因留于新會。自業及融，三世爲守牧，他鄉羈旅，號令不行。至是，夫人誡約本宗，使從民禮。每共寶參決辭訟，首領有犯法者，雖是親族，無所舍縱。自此政令有序，人莫敢違。”按：傳云洗挺爲南梁州刺史，據《梁書》卷二《武帝紀中》，天監八年已於北巴西郡置南梁州，不應嶺南復有",
          "一南梁州，存疑，本表不列。"
        ],
