          "《梁書》卷二二《鄱陽王範傳》：“徵爲領軍將軍、侍中。”卷五五《武陵王紀傳》：“尋改授持節、都督益梁等十三州諸軍事、安西將軍、益州刺史。”按：據《武帝紀》，大同五年範由中書令遷中領軍，則此前範當由益州刺史徵爲中書令，非領軍。",
