        "source_section": "梁方鎮年表・大同三年丁巳（537）・東益州",
        "evidence_lines": [
          "《陳書》卷三一《樊毅傳》：“父文熾，梁散騎常侍、信武將軍、益州刺史。”《南史》卷六七《樊毅傳》：“父文熾，梁散騎常侍、東益州刺史。”卷七四《趙拔扈傳》：“（樊）文茂，黎州刺史文熾弟，襄陽人也。”按：梁益州刺史多任宗室，樊文識當爲東益州或黎州刺史，此從《南史·樊毅傳》。樊文熾大同初爲南梁州刺史，何年爲東益州或黎州刺史不詳，列於此。"
        ],
