        "evidence_lines": [
          "《趙征興墓誌》（《墓誌集成》九七七）：“大梁興運，解巾入仕，調爲電威將軍、湘東王開府中兵參軍事……又出爲東海齊二郡太守……尋遷假節、雲旗將軍、新昭縣開國侯，食邑二千户，成州刺史。……還朝，俄授持節、超武將軍，食邑如故，霍州刺史……仍擢爲使持節、雲勇將軍、始新縣開國侯、都督霍合豫諸軍事、豫州刺史……以梁太清二年，逆寇侯景，侮亂國經……乃仰慕魏氏親鄰之德，以武定七年，翻歸樂土。”按：趙征興所歷成、霍、豫州，年皆不詳，列於此。東魏武定七年即梁",
          "太清三年。太清年間豫州刺史爲羊鴉仁，如誌所云屬實，趙征興任豫州刺史當在太清以前，非在豫州刺史任上降附東魏。"
        ],
